import{z as i,x as o,o as e,c as C,q as t,j as l,D as A,d as a,s,S as n,b as B}from"./chunks/framework.C8m1ZpeB.js";const G=JSON.parse('{"title":"GPU 虚拟化","description":"","frontmatter":{"title":"GPU 虚拟化","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/virt-gpu.md","filePath":"cs/virt-gpu.md","lastUpdated":1791063341000}'),P={name:"cs/virt-gpu.md"};function p(d,E,D,I,h,u){const r=o("Mermaid");return e(),C("div",null,[E[2]||(E[2]=t('<h1 id="gpu-虚拟化" tabindex="-1">GPU 虚拟化 <a class="header-anchor" href="#gpu-虚拟化" aria-label="Permalink to &quot;GPU 虚拟化&quot;">​</a></h1><div class="epigraph"><p>共享边界的粒度每细一档，仲裁逻辑就多一层：直通几乎不加信任面，API 转发把整个运行时变成边界。GPU 之所以难虚拟化，是它把这道交换摆得比网卡和磁盘都陡。</p><footer>—— 据 PCI-SIG SR-IOV、NVIDIA MIG 与容器运行时文档整理</footer></div><p><a href="/cs/virt-network-virtualization">上一课</a>为每包 CPU 讨价还价，网卡的直通选项在轴上卖掉灵活性买回性能。GPU 是同一道题的极端版本：设备有状态（常驻显存、每进程设备地址空间）、内核态驱动与用户态运行时分层、一次 kernel launch 可以跑几百毫秒。主干课的<a href="/cs/sriov-passthrough">SR-IOV 与直通</a>顺口提过「GPU 直通同类但更重」；本课把「重」拆开，给整条共享光谱钉上判据。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>先问为什么不能照抄网卡。第一，网卡无状态：VF 的队列上下文小，迁移时拔了再插；GPU 上下文是整个显存里的页表、流与命令队列。第二，网卡按包仲裁天然细粒度；GPU 的仲裁粒度是 kernel launch，长核正在跑时，别的租户只能等。第三，网卡的软件栈薄；GPU 的关键逻辑一半在用户态运行时（CUDA 这类），导致「驱动」横跨内核模块与容器里的动态库两层。缺口不是造一个更快的模拟设备，而是<strong>选共享边界</strong>：在指令流、硬件分区、时间片、API 调用四档里挑一档，每档的信任面与开销不同。</p><p><span class="marginnote">把仲裁粒度想成剧场排期：网卡像出租车，每载一客计一次费，交接便宜；GPU 的 kernel launch 像包下一整场演出，几百毫秒里舞台只属于一个剧团——其他租户再急也只能等幕间，时间片切不进一个正在跑的核。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把四档摆成一张光谱，逐档标出边界落在谁的代码上。</p><h3 id="四档光谱" tabindex="-1">四档光谱 <a class="header-anchor" href="#四档光谱" aria-label="Permalink to &quot;四档光谱&quot;">​</a></h3><p>直通：整卡经 <a href="/cs/vfio">VFIO</a> 绑给一台虚机，IOMMU 隔离 DMA，hypervisor 不碰数据面；性能近原生，代价是一卡一租户、无共享。硬件分区：把物理资源切开——MIG 在一颗芯片里切出最多七个实例，每个实例有独占的 SM 分片、L2 切片与显存带宽，故障与干扰在硬件层隔离；这一档是 SR-IOV 思想在 GPU 上的对应物。时间片与 MPS：驱动调度器在进程间切上下文，单卡多租户但相互看见吞吐波动；MPS 更进一步把多个进程并进一个上下文，让 kernel launch 并发跑满 SM，省掉切换、也默认放弃客户间的故障隔离——一个进程崩，同上下文的全倒。</p><p><span class="marginnote">MPS 可以译成「合租上下文」：多个进程共用同一张访客证进出显卡，kernel launch 得以并发塞满 SM；合租省掉了每次进门安检（上下文切换），代价是室友出事（进程崩溃）整屋连坐，隔离让给了吞吐。</span>API 转发：应用只说 API，转发器在宿主侧替它调用真卡；隔离靠协议，兼容性钉死在转发器实现了多少 API 上，升级运行时版本就是一次移植工程。</p>',11)),(e(),l(n,null,{default:A(()=>[s(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E5%BA%94%E7%94%A8%E6%88%96%E5%AE%B9%E5%99%A8%22%5D%20--%3E%20Q%7B%22%E9%80%89%E5%85%B1%E4%BA%AB%E8%BE%B9%E7%95%8C%22%7D%0A%20%20Q%20--%3E%7C%22%E6%8C%87%E4%BB%A4%E6%B5%81%22%7C%20PT%5B%22%E7%9B%B4%E9%80%9A%20VFIO%22%5D%0A%20%20Q%20--%3E%7C%22%E7%A1%AC%E4%BB%B6%E5%88%86%E5%8C%BA%22%7C%20MIG%5B%22MIG%20%E5%AE%9E%E4%BE%8B%22%5D%0A%20%20Q%20--%3E%7C%22%E6%97%B6%E9%97%B4%E7%89%87%22%7C%20TS%5B%22%E9%A9%B1%E5%8A%A8%E8%B0%83%E5%BA%A6%E6%88%96%20MPS%22%5D%0A%20%20Q%20--%3E%7C%22API%20%E8%B0%83%E7%94%A8%22%7C%20FWD%5B%22%E8%BD%AC%E5%8F%91%E5%99%A8%22%5D%0A%20%20PT%20--%3E%20ISO1%5B%22%E4%BF%A1%E4%BB%BB%E9%9D%A2%E6%9C%80%E5%B0%8F%2C%20%E6%97%A0%E5%85%B1%E4%BA%AB%22%5D%0A%20%20MIG%20--%3E%20ISO2%5B%22%E7%A1%AC%E4%BB%B6%E9%9A%94%E7%A6%BB%2C%20%E6%9C%80%E5%A4%9A%E4%B8%83%E5%AE%9E%E4%BE%8B%22%5D%0A%20%20TS%20--%3E%20ISO3%5B%22%E9%A9%B1%E5%8A%A8%E4%BB%B2%E8%A3%81%2C%20%E9%9A%94%E7%A6%BB%E5%BC%B1%22%5D%0A%20%20FWD%20--%3E%20ISO4%5B%22%E8%BD%AC%E5%8F%91%E5%99%A8%E5%8D%B3%E8%BE%B9%E7%95%8C%2C%20%E5%85%BC%E5%AE%B9%E7%A8%8E%E9%87%8D%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[a("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,[a("容器把这道题变得日常，因为容器根本不虚拟化 GPU：NVIDIA 式方案把用户态运行时库"),B("strong",null,"挂载"),a("进容器，内核模块留在宿主——容器里没有设备驱动安装这回事，只有库的版本匹配。于是出现独属于 GPU 的版本 skew：容器里的 libcuda 不能比宿主内核模块新，否则旧内核接不住新库的请求。集群里「宿主驱动升级要排空容器」的运维痛，根源就在这层劈开。把上一课的判据搬过来仍然成立："),B("strong",null,"高频路径别付仲裁税"),a("。训练负载整卡独占数天，直通或整卡容器最便宜；推理多实例小模型，MIG 切分换隔离与带宽保障；图形与远程工作站，转发器换部署自由。CPU 靠硬件辅助把细粒度多路复用做得近乎免费（第一课的谱系），GPU 没有等效的历史——它的每一档粒度都真实付费。")],-1)),(e(),l(n,null,{default:A(()=>[s(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20HOSTMOD%5B%22%E5%AE%BF%E4%B8%BB%E5%86%85%E6%A0%B8%E6%A8%A1%E5%9D%97%22%5D%20--%3E%20USRLIB%5B%22%E5%AE%BF%E4%B8%BB%E7%94%A8%E6%88%B7%E6%80%81%E8%BF%90%E8%A1%8C%E6%97%B6%E5%BA%93%22%5D%0A%20%20USRLIB%20--%3E%7C%22%E6%8C%82%E8%BD%BD%E8%BF%9B%E5%AE%B9%E5%99%A8%22%7C%20CLIB%5B%22%E5%AE%B9%E5%99%A8%E5%86%85%E5%90%8C%E5%90%8D%E5%BA%93%22%5D%0A%20%20CLIB%20--%3E%20CHECK%7B%22%E5%AE%B9%E5%99%A8%E5%BA%93%20vs%20%E5%AE%BF%E4%B8%BB%E6%A8%A1%E5%9D%97%2C%20%E8%B0%81%E6%96%B0%3F%22%7D%0A%20%20CHECK%20--%3E%7C%22%E5%AE%B9%E5%99%A8%E5%BA%93%E6%9B%B4%E6%96%B0%22%7C%20SKEW%5B%22%E7%89%88%E6%9C%AC%20skew%3A%20%E6%97%A7%E5%86%85%E6%A0%B8%E6%8E%A5%E4%B8%8D%E4%BD%8F%E6%96%B0%E5%BA%93%E8%AF%B7%E6%B1%82%22%5D%0A%20%20CHECK%20--%3E%7C%22%E5%AE%B9%E5%99%A8%E5%BA%93%E4%B8%8D%E6%96%B0%E4%BA%8E%E6%A8%A1%E5%9D%97%22%7C%20OK%5B%22%E5%8C%B9%E9%85%8D%2C%20%E6%AD%A3%E5%B8%B8%E5%8A%A0%E8%BD%BD%22%5D%0A%20%20SKEW%20--%3E%20OPS%5B%22%E5%AE%BF%E4%B8%BB%E9%A9%B1%E5%8A%A8%E5%8D%87%E7%BA%A7%E9%9C%80%E5%85%88%E6%8E%92%E7%A9%BA%E5%AE%B9%E5%99%A8%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">MIG 的数字实例：把一颗 80GB 的卡切成七份，每份约 10GB 显存与一小片 SM；四个推理实例各占一份后，任何一份被打满都不会拖慢邻居——这是用物理切分把时间片共享的「邻座吵闹」问题整层消掉，代价是没被租出去的分片闲着。</span></p><p><span class="marginnote">显存记账常常比算力更早撞墙：时间片共享下多个进程各自常驻显存，一张 80GB 的卡被四个模型占满后，切换再快也装不下第五个——GPU 的「超售」受制于显存总量，不像 CPU 可以靠时间片凭空多出租户。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给厂商型号表，不写 vGPU 的许可策略，也只承认嵌套与热迁移在 GPU 上仍属边缘能力——显存与上下文状态让<a href="/cs/live-migration">热迁移</a>在 GPU 场景远难于纯 CPU。安全边界的量化留给下一课：时间片与 MPS 的弱隔离恰好是侧信道与干扰问题的入口，MIG 的硬件隔离则相反。还有一条边界：本课不写 ARM 集成显卡与移动端虚拟化，也不写远端渲染的编码链路；对象始终是「数据中心的这张卡由谁共享、以什么为边界」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GPU 难虚拟化源于三点：设备有状态、仲裁粒度是 kernel launch、驱动横跨内核与用户态。</li><li>共享光谱四档：直通、硬件分区（MIG）、时间片与 MPS、API 转发；粒度越细，仲裁信任面越大。</li><li>容器不虚拟化 GPU：用户态库挂载进容器，内核驱动留宿主，版本 skew 由此而来。</li><li>显存是比算力更早耗尽的共享资源；GPU 超售受显存总量硬约束。</li><li>出处：据 PCI-SIG SR-IOV、VFIO、NVIDIA MIG 与容器运行时文档整理。</li></ul>',6))])}const S=i(P,[["render",p]]);export{G as __pageData,S as default};
